CREATE TEMP TABLE removed_box ON COMMIT DROP AS
SELECT id, version_number FROM stop_factors.stop_factor_group WHERE change_reason = 'Правила по просрочкам 2026';

CREATE TEMP TABLE removed_row ON COMMIT DROP AS
SELECT f.id FROM stop_factors.stop_factor f JOIN removed_box b ON b.id = f.group_id;

DELETE FROM stop_factors.stop_factor_check WHERE stop_factor_id IN (SELECT id FROM removed_row);
DELETE FROM stop_factors.stop_factor_condition WHERE stop_factor_id IN (SELECT id FROM removed_row);
DELETE FROM stop_factors.stop_factor_product WHERE stop_factor_id IN (SELECT id FROM removed_row);
DELETE FROM stop_factors.stop_factor WHERE id IN (SELECT id FROM removed_row);
DELETE FROM stop_factors.stop_factor_group WHERE id IN (SELECT id FROM removed_box);

UPDATE stop_factors.stop_factor_group g
SET valid_to = NULL
FROM removed_box b
WHERE g.version_number = b.version_number - 1;
